Voici un exemple de programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    // Nom du fichier à lire
    const std::string filename = "input.txt";

    // Mot à rechercher
    const std::string search_word = "example";

    // Variable pour stocker le nombre d'occurrences
    int count = 0;

    // Ouverture du fichier
    std::ifstream file(filename);

    if (!file) {
        std::cerr << "Impossible d'ouvrir le fichier " << filename << std::endl;
        return 1;
    }

    // Lecture ligne par ligne
    std::string line;
    while (std::getline(file, line)) {
        // Conversion en minuscules pour une recherche insensible à la casse
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Recherche du mot dans la ligne
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            // Incrémentation du compteur si le mot est trouvé
            count++;
            // Mise à jour de la position de la prochaine occurrence
            pos += search_word.length();
        }
    }

    // Fermeture du fichier
    file.close();

    // Affichage du résultat
    std::cout << "Le mot \"" << search_word << "\" apparait " << count << " fois dans le fichier " << filename << std::endl;

    return 0;
}
```

Pour utiliser ce programme :

1. Sauvegardez le code dans un fichier `.cpp` (par exemple `search_word_counter.cpp`).
2. Ouvrez une invite de commande ou un terminal dans le répertoire où se trouve le fichier.
